-- Identity and shared database conventions (ADR-0002).
-- Conventions: uuid PKs (UUIDv7, generated by the application), timestamptz audit columns,
-- optimistic-lock "version", enums as text + CHECK, lower-case slug business keys.

-- Rejects mutation of immutable / append-only rows. Attached per table in later migrations.
create function forbid_mutation() returns trigger
    language plpgsql as
$$
begin
    raise exception '% on table % is not allowed: rows are immutable', tg_op, tg_table_name
        using errcode = 'P0001';
end;
$$;

create table app_user
(
    id           uuid primary key,
    username     varchar(64)  not null,
    display_name varchar(200) not null,
    email        varchar(320),
    status       varchar(16)  not null,
    created_at   timestamptz  not null,
    updated_at   timestamptz  not null,
    version      bigint       not null,
    constraint uk_app_user_username unique (username),
    constraint uk_app_user_email unique (email),
    constraint ck_app_user_username check (username ~ '^[a-z0-9][a-z0-9._-]{1,63}$'),
    constraint ck_app_user_email_lower check (email = lower(email)),
    constraint ck_app_user_status check (status in ('ACTIVE', 'DISABLED'))
);
